#include<bits/stdc++.h>
#define PII pair<ll,ll>
#define max(a,b) ((a)>(b)?(a):(b))
#define min(a,b) ((a)<(b)?(a):(b))
using namespace std;
typedef long long ll;
const ll INF=0x3f3f3f3f3f3f3f3f;
const ll N=1e3+5,M=1e5+5;
const ll maxlen=1e5;
struct seg{
    ll id;
    ll l,r,h;
    friend bool operator<(seg x,seg y){
        return x.h<y.h;
    }
}a[N];
struct seg_tree{
    struct node{
        ll l,r;
        int col,tag;
    }tr[M<<2];
    void pushdown(ll p){
        mktag(p<<1,tr[p].tag);
        mktag(p<<1|1,tr[p].tag);
        tr[p].tag=0;
    }
    void mktag(ll p,ll k){
        if(tr[p].r==tr[p].l)tr[p].col=k;
        tr[p].tag=k;
    }
    void build(ll p,ll l,ll r){
        tr[p].l=l,tr[p].r=r;
        if(l==r){
            tr[p].col=tr[p].tag=0;
            return;
        }
        ll mid=(l+r)>>1;
        build(p<<1,l,mid);
        build(p<<1|1,mid+1,r);
    }
    void update(ll p,ll ql,ll qr,ll k){
        ll l=tr[p].l,r=tr[p].r;
        if(ql<=l&&r<=qr){
            mktag(p,k);
            return;
        }
        if(tr[p].tag)pushdown(p);
        ll mid=(l+r)>>1;
        if(ql<=mid)update(p<<1,ql,qr,k);
        if(qr>mid)update(p<<1|1,ql,qr,k);
    }
    ll query(ll p,ll q){
        ll l=tr[p].l,r=tr[p].r;
        if(l==r)return tr[p].col;
        if(tr[p].tag)pushdown(p);
        ll mid=(l+r)>>1;
        if(q<=mid)return query(p<<1,q);
        else return query(p<<1|1,q);
    }
}Tr; 
ll n,S,T,news,newt;
vector<PII>G[N<<2]; 
ll dis[N<<2],vis[N<<2]; 
ll pos[N<<2]; 
void add(ll u,ll v,ll w){
    G[u].push_back({v,w});
}
int main(){
	ios::sync_with_stdio(0);
    Tr.build(1,1,maxlen);
    cin>>n>>S>>T;
    for(ll i=1;i<=n;i++)cin>>a[i].l>>a[i].r>>a[i].h,a[i].id=i;
    sort(a+1,a+1+n); 
    ll cnt=n*2;
    for(ll i=1;i<=n;i++){ 
        pos[i*2-1]=i;
        pos[i*2]=i;
        add(i*2-1,i*2,a[i].r-a[i].l);
        add(i*2,i*2-1,a[i].r-a[i].l); 
        ll lid=Tr.query(1,a[i].l); 
        if(lid!=0){
            pos[++cnt]=lid; 
            add(i*2-1,cnt,a[i].h-a[lid].h); 
            add(cnt,lid*2-1,a[i].l-a[lid].l);
            add(cnt,lid*2,a[lid].r-a[i].l); 
        }
        ll rid=Tr.query(1,a[i].r);
        if(rid!=0){

            pos[++cnt]=rid;
            add(i*2,cnt,a[i].h-a[rid].h);
            add(cnt,rid*2-1,a[i].r-a[rid].l);
            add(cnt,rid*2,a[rid].r-a[i].r);
        }
        Tr.update(1,a[i].l,a[i].r,i);
        if(a[i].id==S)news=i*2-1;
        if(a[i].id==T)newt=i;
    }
    memset(dis,0x3f,sizeof dis); 
    dis[news]=0;
    priority_queue<PII>q;
    q.push({0,news});
    while(!q.empty()){
        PII tmp=q.top();
        q.pop();
        ll u=tmp.second;
        if(vis[u])continue;
        vis[u]=1;
        for(PII e:G[u]){
            ll v=e.first;
            if(dis[u]+e.second<dis[v]){
                dis[v]=dis[u]+e.second;
                q.push({-dis[v],v});
            }
        }
    }
    ll ans=INF;
    for(int i=1;i<=cnt;i++){
        if(pos[i]==newt)ans=min(ans,dis[i]); 
    }
    if(ans<INF)cout<<ans<<endl;
    else cout<<"-1\n";
	return 0;
}
